def run():
    out = {"saved_actors": [], "dirty": []}
    for a in T("scene.find_actors", name="", tag="", collision_channels=[]):
        lab = T("actor.get_label", actor=a)
        if lab in ("Colosseum", "HordeDirector", "PlayerStart", "ArenaNavBounds"):
            T("scene.save_actor", actor=a)
            out["saved_actors"].append(lab)
    for p in PKGS:
        try:
            if T("asset.is_dirty", asset_path=p):
                out["dirty"].append(p)
        except Exception as e:
            out.setdefault("err", []).append(p[-8:] + ":" + str(e)[:60])
    if out["dirty"]:
        try:
            T("asset.save_assets", asset_paths=out["dirty"])
        except Exception as e:
            out["save_err"] = str(e)[:300]
    return out
